[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:HowTo ;
                    schema1:step [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalProperty <https://ada.astromat.org/metadata/parameter/module/Core/constantsReferenceValuesDefault>,
                                <https://ada.astromat.org/metadata/parameter/module/ICPMS/isotopeDilutionDataReductionMethod> ;
                            schema1:additionalType ns1:LabProcess ;
                            schema1:name "Data processing" ;
                            schema1:position 3 ;
                            ns2:detectionLimitMethod "no value available: ada:detectionLimitMethod" ],
                        [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalType ns1:LabProcess ;
                            schema1:description "Soils oven-dried (50 °C, 7 days), not sieved; total-dissolution (TD) and aqua-regia (AR) splits; the SC-SF-ICP-MS splits 'redissolved and diluted to 2 ml in high purity 2% HNO3 doped with 1 ppb of high-purity thallium' — §2.1, §2.2, §2.4; the rock chips were analysed by MC-ICP-MS only" ;
                            schema1:name "Sample preparation" ;
                            schema1:position 1 ],
                        [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalType ns1:LabProcess ;
                            schema1:description "TD HNO3 leach (3 ml conc. HNO3, 80 °C, 48 h, leachate discarded); TD HF (4 ml conc. HF, 100 °C, 48 h, evaporated); TD HNO3 (2 × 1 ml conc. HNO3, 100 °C); TD HCl (5 ml 6 M HCl, 80 °C, 15 h, then centrifuged); AR leach (3 ml aqua regia, 3:1 HCl:HNO3, 20 °C, 15 h, then centrifuged) — §2.2" ;
                            schema1:name "Sample digestion" ;
                            schema1:position 4 ;
                            ns1:reagent [ a schema1:DefinedTerm ;
                                    schema1:name "TD HNO3 leach: conc. HNO3; TD HF: conc. HF; TD HNO3: conc. HNO3; TD HCl: 6 M HCl; AR leach: aqua regia (3:1 HCl:HNO3) — §2.2" ] ],
                        [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalType ns1:LabProcess ;
                            schema1:description "no value available: schema:description" ;
                            schema1:name "Data acquisition" ;
                            schema1:position 2 ] ] ;
            sh:resultMessage "A HowTo methodology must have a schema:name" ;
            sh:resultPath schema1:name ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:message "A HowTo methodology must have a schema:name" ;
                    sh:minCount 1 ;
                    sh:path schema1:name ;
                    sh:severity sh:Violation ] ] .

